def format_ts(words, export_name):
    lines = [
        "import { N4VocabItem } from './types';",
        f"export const {export_name}: N4VocabItem[] = ["
    ]
    for w in words:
        item = {
            "id": w[0],
            "kanji": w[1],
            "hiragana": w[2],
            "romaji": w[3],
            "bn": w[4],
            "categoryKey": w[5],
            "category": w[6],
            "lesson": w[7],
            "partOfSpeech": w[8],
            "exampleJp": w[9],
            "exampleFurigana": w[10],
            "exampleRomaji": w[11],
            "exampleBn": w[12],
            "context": w[13],
            "jlpt": "N4"
        }
        lines.append("  " + json.dumps(item, ensure_ascii=False) + ",")
    lines.append("];")
    return "\n".join(lines)

with open("src/data/n4/lesson36_40.ts", "w", encoding="utf-8") as f:
    f.write(format_ts(part3_words, "N4_LESSON_36_40"))

print(f"Generated src/data/n4/lesson36_40.ts with {len(part3_words)} items.")
